Literal.Value:
'{
  "padding": 0,
  "params": [
    {
      "name": "title",
      "value": "KPI"
    },
    {
      "name": "valueHeader",
      "value": "Actual"
    },
    {
      "name": "comparisonLabel",
      "value": "Target"
    },
    {
      "name": "deltaHeader",
      "value": "Var"
    },
    {
      "name": "sortBy",
      "value": "none"
    },
    {
      "name": "statusStyle",
      "value": "bar"
    },
    {
      "name": "lowerIsBetter",
      "value": [
        "Cost",
        "Returns Rate"
      ]
    },
    {
      "name": "showTarget",
      "value": true
    },
    {
      "name": "valueFormat",
      "value": "auto"
    },
    {
      "name": "prefix",
      "value": "$"
    },
    {
      "name": "pctFormat",
      "value": "+.1%"
    },
    {
      "name": "noDataText",
      "value": "n/a"
    },
    {
      "name": "varianceUnit",
      "value": "auto"
    },
    {
      "name": "higherIsBetter",
      "value": true
    },
    {
      "name": "colorGood",
      "expr": "pbiColor(''good'')"
    },
    {
      "name": "colorBad",
      "expr": "pbiColor(''bad'')"
    },
    {
      "name": "colorNeutral",
      "expr": "pbiColor(''neutral'')"
    },
    {
      "name": "arrowUp",
      "value": "▲"
    },
    {
      "name": "arrowDown",
      "value": "▼"
    },
    {
      "name": "arrowFlat",
      "value": "►"
    },
    {
      "name": "cardColor",
      "value": "#FFFFFF"
    },
    {
      "name": "borderColor",
      "value": "#E1DFDD"
    },
    {
      "name": "borderWidth",
      "value": 1
    },
    {
      "name": "cardRadius",
      "value": 4
    },
    {
      "name": "valueColor",
      "expr": "pbiColor(0, -0.5)"
    },
    {
      "name": "labelColor",
      "value": "#605E5C"
    },
    {
      "name": "mutedColor",
      "value": "#A19F9D"
    },
    {
      "name": "trackColor",
      "value": "#EDEBE9"
    },
    {
      "name": "rowLineColor",
      "value": "#EDEBE9"
    },
    {
      "name": "unit",
      "expr": "clamp(min(width / 360, height / 140), 0.8, 2)"
    },
    {
      "name": "pad",
      "expr": "12 * unit"
    },
    {
      "name": "fontSize",
      "expr": "12 * unit"
    },
    {
      "name": "headerSize",
      "expr": "10 * unit"
    },
    {
      "name": "headerH",
      "expr": "22 * unit"
    },
    {
      "name": "minRowH",
      "expr": "18 * unit"
    },
    {
      "name": "maxRowH",
      "expr": "30 * unit"
    },
    {
      "name": "statusW",
      "expr": "statusStyle === ''bar'' ? clamp(width * 0.16, 28, 80 * unit) : 10 * unit"
    },
    {
      "name": "statusX1",
      "expr": "width - pad"
    },
    {
      "name": "statusX0",
      "expr": "statusX1 - statusW"
    },
    {
      "name": "deltaRight",
      "expr": "statusX0 - 10 * unit"
    },
    {
      "name": "targetOn",
      "expr": "showTarget && width >= 360"
    },
    {
      "name": "targetRight",
      "expr": "deltaRight - 70 * unit"
    },
    {
      "name": "valueRight",
      "expr": "targetOn ? targetRight - 50 * unit : deltaRight - 70 * unit"
    },
    {
      "name": "nameLimit",
      "expr": "max(20, valueRight - 52 * unit - pad - 6)"
    }
  ],
  "data": {
    "name": "dataset"
  },
  "transform": [
    {
      "window": [
        {
          "op": "row_number",
          "as": "rowIn"
        }
      ]
    },
    {
      "aggregate": [
        {
          "op": "sum",
          "field": "Value",
          "as": "vSum"
        },
        {
          "op": "valid",
          "field": "Value",
          "as": "vN"
        },
        {
          "op": "sum",
          "field": "Target",
          "as": "tgSum"
        },
        {
          "op": "valid",
          "field": "Target",
          "as": "tgN"
        },
        {
          "op": "min",
          "field": "rowIn",
          "as": "firstRow"
        }
      ],
      "groupby": [
        "KPI Name",
        "Format"
      ]
    },
    {
      "calculate": "datum.vN > 0 ? datum.vSum : null",
      "as": "v"
    },
    {
      "calculate": "datum.tgN > 0 ? datum.tgSum : null",
      "as": "tg"
    },
    {
      "calculate": "isValid(datum[''KPI Name'']) ? datum[''KPI Name''] + '''' : noDataText",
      "as": "name"
    },
    {
      "calculate": "isValid(datum[''Format'']) ? datum[''Format''] + '''' : ''''",
      "as": "fmtRaw"
    },
    {
      "calculate": "datum.fmtRaw === ''auto'' || (length(datum.fmtRaw) > 0 && test(/^(?:(.)?([<>=^]))?([+\\-( ])?([$#])?(0)?(\\d+)?(,)?(\\.\\d+)?(~)?([a-z%])?$/i, datum.fmtRaw)) ? datum.fmtRaw : valueFormat",
      "as": "f"
    },
    {
      "calculate": "(indexof(lowerIsBetter, datum.name) >= 0 ? -1 : 1) * (higherIsBetter ? 1 : -1)",
      "as": "dir"
    },
    {
      "calculate": "isValid(datum.v) && isValid(datum.tg) ? datum.v - datum.tg : null",
      "as": "d"
    },
    {
      "calculate": "isValid(datum.d) && datum.tg !== 0 ? datum.d / abs(datum.tg) : null",
      "as": "p"
    },
    {
      "calculate": "isValid(datum.v) && isValid(datum.tg) && datum.tg !== 0 ? datum.v / datum.tg : null",
      "as": "r"
    },
    {
      "calculate": "isValid(datum.d) ? datum.dir * datum.d : 0",
      "as": "g"
    },
    {
      "calculate": "(datum.g > 0 ? colorGood : datum.g < 0 ? colorBad : colorNeutral)",
      "as": "statusColor"
    },
    {
      "calculate": "(varianceUnit === ''points'' || (varianceUnit === ''auto'' && indexof(datum.f, ''%'') >= 0))",
      "as": "isPts"
    },
    {
      "calculate": "(!isValid(datum.v) || !isFinite(datum.v) ? noDataText : datum.f !== ''auto'' ? format(datum.v, datum.f) : (datum.v < 0 ? ''−'' : '''') + prefix + format(abs(datum.v) / (abs(datum.v) >= 999.5e6 ? 1e9 : abs(datum.v) >= 999.5e3 ? 1e6 : abs(datum.v) >= 999.5 ? 1e3 : 1), abs(datum.v) / (abs(datum.v) >= 999.5e6 ? 1e9 : abs(datum.v) >= 999.5e3 ? 1e6 : abs(datum.v) >= 999.5 ? 1e3 : 1) < 10 ? ((abs(datum.v) >= 999.5e6 ? 1e9 : abs(datum.v) >= 999.5e3 ? 1e6 : abs(datum.v) >= 999.5 ? 1e3 : 1) > 1 ? ''.1f'' : ''.2~f'') : '',.0f'') + (abs(datum.v) >= 999.5e6 ? ''bn'' : abs(datum.v) >= 999.5e3 ? ''M'' : abs(datum.v) >= 999.5 ? ''K'' : ''''))",
      "as": "valueText"
    },
    {
      "calculate": "(!isValid(datum.tg) || !isFinite(datum.tg) ? noDataText : datum.f !== ''auto'' ? format(datum.tg, datum.f) : (datum.tg < 0 ? ''−'' : '''') + prefix + format(abs(datum.tg) / (abs(datum.tg) >= 999.5e6 ? 1e9 : abs(datum.tg) >= 999.5e3 ? 1e6 : abs(datum.tg) >= 999.5 ? 1e3 : 1), abs(datum.tg) / (abs(datum.tg) >= 999.5e6 ? 1e9 : abs(datum.tg) >= 999.5e3 ? 1e6 : abs(datum.tg) >= 999.5 ? 1e3 : 1) < 10 ? ((abs(datum.tg) >= 999.5e6 ? 1e9 : abs(datum.tg) >= 999.5e3 ? 1e6 : abs(datum.tg) >= 999.5 ? 1e3 : 1) > 1 ? ''.1f'' : ''.2~f'') : '',.0f'') + (abs(datum.tg) >= 999.5e6 ? ''bn'' : abs(datum.tg) >= 999.5e3 ? ''M'' : abs(datum.tg) >= 999.5 ? ''K'' : ''''))",
      "as": "targetText"
    },
    {
      "calculate": "(!isValid(datum.d) ? '''' : datum.d > 0 ? arrowUp : datum.d < 0 ? arrowDown : arrowFlat) + '' '' + (datum.isPts ? (!isValid(datum.d) ? noDataText : (datum.d > 0 ? ''+'' : datum.d < 0 ? ''−'' : '''') + format(abs(datum.d) * 100, ''.1f'') + '' pts'') : (!isValid(datum.p) || !isFinite(datum.p) ? noDataText : format(datum.p, pctFormat)))",
      "as": "deltaText"
    },
    {
      "calculate": "sortBy === ''value'' ? (isValid(datum.v) ? -datum.v : 1e300) : sortBy === ''status'' ? (isValid(datum.p) ? datum.dir * datum.p : 1e300) : sortBy === ''name'' ? 0 : datum.firstRow",
      "as": "sortKey"
    },
    {
      "window": [
        {
          "op": "row_number",
          "as": "rank"
        }
      ],
      "sort": [
        {
          "field": "sortKey",
          "order": "ascending"
        },
        {
          "field": "name",
          "order": "ascending"
        }
      ]
    },
    {
      "joinaggregate": [
        {
          "op": "count",
          "as": "n"
        }
      ]
    },
    {
      "calculate": "max(1, floor((height - headerH - pad / 2) / minRowH))",
      "as": "rowsFit"
    },
    {
      "calculate": "datum.n <= datum.rowsFit ? datum.n : max(1, datum.rowsFit - 1)",
      "as": "shown"
    },
    {
      "calculate": "clamp((height - headerH - pad / 2) / min(datum.n, datum.rowsFit), minRowH, maxRowH)",
      "as": "rowH"
    },
    {
      "calculate": "headerH + (datum.rank - 0.5) * datum.rowH",
      "as": "cy"
    },
    {
      "calculate": "headerH + (datum.rank - 1) * datum.rowH",
      "as": "lineY"
    },
    {
      "calculate": "clamp(isValid(datum.r) ? datum.r : 0, 0, 1.25) / 1.25",
      "as": "barFrac"
    },
    {
      "calculate": "statusX0",
      "as": "sx0"
    },
    {
      "calculate": "statusX1",
      "as": "sx1"
    },
    {
      "calculate": "statusX0 + datum.barFrac * statusW",
      "as": "fillX"
    },
    {
      "calculate": "statusX0 + statusW / 1.25",
      "as": "tickX"
    },
    {
      "calculate": "datum.cy - 3.5 * unit",
      "as": "barY0"
    },
    {
      "calculate": "datum.cy + 3.5 * unit",
      "as": "barY1"
    },
    {
      "calculate": "datum.cy - 6 * unit",
      "as": "tickY0"
    },
    {
      "calculate": "datum.cy + 6 * unit",
      "as": "tickY1"
    },
    {
      "calculate": "statusX1 - 5 * unit",
      "as": "dotX"
    },
    {
      "calculate": "PI * pow(4.5 * unit, 2)",
      "as": "dotSize"
    },
    {
      "calculate": "''+'' + (datum.n - datum.shown) + '' more''",
      "as": "moreText"
    },
    {
      "calculate": "pad",
      "as": "lx0"
    },
    {
      "calculate": "width - pad",
      "as": "lx1"
    }
  ],
  "layer": [
    {
      "description": "Card background and border, inset by half the border so the container never clips it",
      "data": {
        "values": [
          {}
        ]
      },
      "mark": {
        "type": "rect",
        "x": {
          "expr": "borderWidth / 2"
        },
        "y": {
          "expr": "borderWidth / 2"
        },
        "x2": {
          "expr": "width - borderWidth / 2"
        },
        "y2": {
          "expr": "height - borderWidth / 2"
        },
        "fill": {
          "expr": "cardColor"
        },
        "stroke": {
          "expr": "borderColor"
        },
        "strokeWidth": {
          "expr": "borderWidth"
        },
        "cornerRadius": {
          "expr": "cardRadius"
        }
      }
    },
    {
      "description": "Header: name column",
      "data": {
        "values": [
          {}
        ]
      },
      "mark": {
        "type": "text",
        "align": "left",
        "baseline": "alphabetic",
        "fontWeight": 600,
        "x": {
          "expr": "pad"
        },
        "y": {
          "expr": "headerH * 0.68"
        },
        "fontSize": {
          "expr": "headerSize"
        },
        "limit": {
          "expr": "nameLimit"
        },
        "fill": {
          "expr": "labelColor"
        },
        "text": {
          "expr": "title"
        }
      }
    },
    {
      "description": "Header: values",
      "data": {
        "values": [
          {}
        ]
      },
      "mark": {
        "type": "text",
        "align": "right",
        "baseline": "alphabetic",
        "fontWeight": 600,
        "x": {
          "expr": "valueRight"
        },
        "y": {
          "expr": "headerH * 0.68"
        },
        "fontSize": {
          "expr": "headerSize"
        },
        "fill": {
          "expr": "labelColor"
        },
        "text": {
          "expr": "valueHeader"
        }
      }
    },
    {
      "description": "Header: targets",
      "data": {
        "values": [
          {}
        ]
      },
      "transform": [
        {
          "filter": "targetOn"
        }
      ],
      "mark": {
        "type": "text",
        "align": "right",
        "baseline": "alphabetic",
        "fontWeight": 600,
        "x": {
          "expr": "targetRight"
        },
        "y": {
          "expr": "headerH * 0.68"
        },
        "fontSize": {
          "expr": "headerSize"
        },
        "fill": {
          "expr": "labelColor"
        },
        "text": {
          "expr": "comparisonLabel"
        }
      }
    },
    {
      "description": "Header: variances",
      "data": {
        "values": [
          {}
        ]
      },
      "mark": {
        "type": "text",
        "align": "right",
        "baseline": "alphabetic",
        "fontWeight": 600,
        "x": {
          "expr": "deltaRight"
        },
        "y": {
          "expr": "headerH * 0.68"
        },
        "fontSize": {
          "expr": "headerSize"
        },
        "fill": {
          "expr": "labelColor"
        },
        "text": {
          "expr": "deltaHeader"
        }
      }
    },
    {
      "description": "Line under the header",
      "data": {
        "values": [
          {}
        ]
      },
      "transform": [
        {
          "calculate": "pad",
          "as": "lx0"
        },
        {
          "calculate": "width - pad",
          "as": "lx1"
        },
        {
          "calculate": "headerH",
          "as": "ly"
        }
      ],
      "mark": {
        "type": "rule",
        "stroke": {
          "expr": "borderColor"
        },
        "strokeWidth": 1
      },
      "encoding": {
        "x": {
          "field": "lx0",
          "type": "quantitative",
          "scale": null
        },
        "x2": {
          "field": "lx1"
        },
        "y": {
          "field": "ly",
          "type": "quantitative",
          "scale": null
        },
        "y2": {
          "field": "ly"
        }
      }
    },
    {
      "description": "Lines between rows",
      "transform": [
        {
          "filter": "datum.rank > 1 && datum.rank <= datum.shown + (datum.n > datum.shown ? 1 : 0)"
        }
      ],
      "mark": {
        "type": "rule",
        "stroke": {
          "expr": "rowLineColor"
        },
        "strokeWidth": 1
      },
      "encoding": {
        "x": {
          "field": "lx0",
          "type": "quantitative",
          "scale": null
        },
        "x2": {
          "field": "lx1"
        },
        "y": {
          "field": "lineY",
          "type": "quantitative",
          "scale": null
        },
        "y2": {
          "field": "lineY"
        }
      }
    },
    {
      "description": "KPI name",
      "transform": [
        {
          "filter": "datum.rank <= datum.shown"
        }
      ],
      "mark": {
        "type": "text",
        "align": "left",
        "baseline": "middle",
        "fontWeight": "normal",
        "x": {
          "expr": "pad"
        },
        "fontSize": {
          "expr": "fontSize"
        },
        "limit": {
          "expr": "nameLimit"
        },
        "fill": {
          "expr": "labelColor"
        }
      },
      "encoding": {
        "y": {
          "field": "cy",
          "type": "quantitative",
          "scale": null
        },
        "text": {
          "field": "name",
          "type": "nominal"
        },
        "tooltip": [
          {
            "field": "name",
            "type": "nominal",
            "title": "KPI"
          },
          {
            "field": "valueText",
            "type": "nominal",
            "title": "Actual"
          },
          {
            "field": "targetText",
            "type": "nominal",
            "title": "Target"
          },
          {
            "field": "deltaText",
            "type": "nominal",
            "title": "Variance"
          }
        ]
      }
    },
    {
      "description": "Value",
      "transform": [
        {
          "filter": "datum.rank <= datum.shown"
        }
      ],
      "mark": {
        "type": "text",
        "align": "right",
        "baseline": "middle",
        "fontWeight": "bold",
        "x": {
          "expr": "valueRight"
        },
        "fontSize": {
          "expr": "fontSize"
        },
        "fill": {
          "expr": "valueColor"
        }
      },
      "encoding": {
        "y": {
          "field": "cy",
          "type": "quantitative",
          "scale": null
        },
        "text": {
          "field": "valueText",
          "type": "nominal"
        },
        "tooltip": [
          {
            "field": "name",
            "type": "nominal",
            "title": "KPI"
          },
          {
            "field": "valueText",
            "type": "nominal",
            "title": "Actual"
          },
          {
            "field": "targetText",
            "type": "nominal",
            "title": "Target"
          },
          {
            "field": "deltaText",
            "type": "nominal",
            "title": "Variance"
          }
        ]
      }
    },
    {
      "description": "Target",
      "transform": [
        {
          "filter": "targetOn && datum.rank <= datum.shown"
        }
      ],
      "mark": {
        "type": "text",
        "align": "right",
        "baseline": "middle",
        "fontWeight": "normal",
        "x": {
          "expr": "targetRight"
        },
        "fontSize": {
          "expr": "fontSize"
        },
        "fill": {
          "expr": "labelColor"
        }
      },
      "encoding": {
        "y": {
          "field": "cy",
          "type": "quantitative",
          "scale": null
        },
        "text": {
          "field": "targetText",
          "type": "nominal"
        }
      }
    },
    {
      "description": "Variance, coloured good or bad",
      "transform": [
        {
          "filter": "datum.rank <= datum.shown"
        }
      ],
      "mark": {
        "type": "text",
        "align": "right",
        "baseline": "middle",
        "fontWeight": 600,
        "x": {
          "expr": "deltaRight"
        },
        "fontSize": {
          "expr": "fontSize"
        }
      },
      "encoding": {
        "y": {
          "field": "cy",
          "type": "quantitative",
          "scale": null
        },
        "text": {
          "field": "deltaText",
          "type": "nominal"
        },
        "color": {
          "field": "statusColor",
          "type": "nominal",
          "scale": null
        }
      }
    },
    {
      "description": "Mini bar track",
      "transform": [
        {
          "filter": "statusStyle === ''bar'' && datum.rank <= datum.shown"
        }
      ],
      "mark": {
        "type": "rect",
        "fill": {
          "expr": "trackColor"
        }
      },
      "encoding": {
        "x": {
          "field": "sx0",
          "type": "quantitative",
          "scale": null
        },
        "x2": {
          "field": "sx1"
        },
        "y": {
          "field": "barY0",
          "type": "quantitative",
          "scale": null
        },
        "y2": {
          "field": "barY1"
        }
      }
    },
    {
      "description": "Mini bar: Value against Target, to 125%",
      "transform": [
        {
          "filter": "statusStyle === ''bar'' && datum.rank <= datum.shown && datum.fillX > datum.sx0"
        }
      ],
      "mark": {
        "type": "rect"
      },
      "encoding": {
        "x": {
          "field": "sx0",
          "type": "quantitative",
          "scale": null
        },
        "x2": {
          "field": "fillX"
        },
        "y": {
          "field": "barY0",
          "type": "quantitative",
          "scale": null
        },
        "y2": {
          "field": "barY1"
        },
        "color": {
          "field": "statusColor",
          "type": "nominal",
          "scale": null
        },
        "tooltip": [
          {
            "field": "name",
            "type": "nominal",
            "title": "KPI"
          },
          {
            "field": "valueText",
            "type": "nominal",
            "title": "Actual"
          },
          {
            "field": "targetText",
            "type": "nominal",
            "title": "Target"
          },
          {
            "field": "deltaText",
            "type": "nominal",
            "title": "Variance"
          }
        ]
      }
    },
    {
      "description": "Mini bar: target tick at 100%",
      "transform": [
        {
          "filter": "statusStyle === ''bar'' && datum.rank <= datum.shown"
        }
      ],
      "mark": {
        "type": "rule",
        "stroke": {
          "expr": "valueColor"
        },
        "strokeWidth": {
          "expr": "1.5 * unit"
        }
      },
      "encoding": {
        "x": {
          "field": "tickX",
